1	//! `.beam` container writer — the mirror image of [`super::decode`].
2	//!
3	//! Feature-gated behind `encode` (default-off, zero new dependencies). Shares
4	//! the decoder's `Operand`, `Instruction`, and chunk types, so no format
5	//! knowledge is duplicated: every encoder is an exact inverse of its decoder,
6	//! and the round-trip suite (`decode(encode(decode(x))) == decode(x)`) is the
7	//! ratchet that keeps them aligned.
8	
9	mod chunks;
10	mod code;
11	mod compact;
12	mod container;
13	mod literals;
14	mod opcodes;
15	
16	pub use container::{EncodeError, encode_module};

1	//! IFF container writer + the public `encode_module` entry point.
2	//!
3	//! Frames chunk bodies into the `FOR1`/`BEAM` container (4-byte chunk headers,
4	//! 4-byte alignment padding) in a fixed canonical order and stamps the outer
5	//! size, mirroring `loader::parser::parse_beam_chunks`.
6	
7	use std::error::Error;
8	use std::fmt;
9	
10	use crate::atom::AtomTable;
11	use crate::loader::ParsedModule;
12	
13	use super::chunks::{
14	    encode_atom_chunk, encode_export_chunk, encode_import_chunk, encode_lambda_chunk,
15	    encode_line_chunk, encode_string_chunk,
16	};
17	use super::code::encode_code_chunk;
18	use super::compact::AtomEncoder;
19	use super::literals::encode_literal_chunk;
20	
21	/// A `.beam` module could not be encoded.
22	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
23	pub enum EncodeError {
24	    /// An operand referenced an atom absent from the module's atom table, or an
25	    /// atom could not be resolved to a name.
26	    AtomNotInTable,
27	    /// A count, index, or length exceeded the width its chunk field allows.
28	    ValueOutOfRange,
29	    /// A `Literal::BigInteger` payload was not a sign byte plus magnitude.
30	    MalformedBigInteger,
31	    /// An instruction shape cannot be expressed (e.g. a `MakeFun` with an
32	    /// operand count matching neither `make_fun2` nor `make_fun3`).
33	    UnsupportedInstruction,
34	    /// A typed-register operand was reached in a module that carries no
35	    /// `Type` chunk. OTP 26+ emits `#tr{}` operands carrying an index into
36	    /// that chunk; with no chunk to re-emit, writing the operand would
37	    /// produce a `Code` chunk pointing into a table absent from the
38	    /// container — readable by beamr (which ignores the table) and unreadable
39	    /// by every other BEAM tool, a silent fallback wearing a success exit.
40	    ///
41	    /// Since #95's fix, `ParsedModule::type_chunk` carries the chunk bytes
42	    /// verbatim and typed registers encode whenever it is present, so this
43	    /// error is reachable only for modules CONSTRUCTED with typed registers
44	    /// and `type_chunk: None` — a combination no decoded module produces.
45	    TypedRegisterWithoutTypeChunk {
46	        /// Position in the module's instruction stream, when the operand was
47	        /// reached through the `Code` chunk walk. `None` when an operand is
48	        /// encoded outside that walk, where no index exists to report.
49	        instruction_index: Option<usize>,
50	        /// The `Type` chunk entry the operand names — the datum that has no
51	        /// home in the emitted container.
52	        type_index: u64,
53	    },
54	}
55	
56	impl EncodeError {
57	    /// Attaches an instruction position to an error raised while encoding that
58	    /// instruction's operands. Errors that carry no position are unchanged.
59	    pub(crate) fn at_instruction(self, index: usize) -> Self {
60	        match self {
61	            Self::TypedRegisterWithoutTypeChunk { type_index, .. } => {
62	                Self::TypedRegisterWithoutTypeChunk {
63	                    instruction_index: Some(index),
64	                    type_index,
65	                }
66	            }
67	            other => other,
68	        }
69	    }
70	}
71	
72	impl fmt::Display for EncodeError {
73	    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
74	        match self {
75	            Self::AtomNotInTable => {
76	                formatter.write_str("operand atom is absent from the module atom table")
77	            }
78	            Self::ValueOutOfRange => {
79	                formatter.write_str("value exceeds the width of its BEAM chunk field")
80	            }
81	            Self::MalformedBigInteger => {
82	                formatter.write_str("big-integer literal is not a sign byte plus magnitude")
83	            }
84	            Self::UnsupportedInstruction => {
85	                formatter.write_str("instruction shape cannot be encoded")
86	            }
87	            Self::TypedRegisterWithoutTypeChunk {
88	                instruction_index,
89	                type_index,
90	            } => {
91	                write!(
92	                    formatter,
93	                    "typed-register operand names `Type` chunk entry {type_index}, \
94	                     which this encoder does not emit"
95	                )?;
96	                match instruction_index {
97	                    Some(index) => write!(formatter, " (instruction {index})"),
98	                    None => Ok(()),
99	                }
100	            }
101	        }
102	    }
103	}
104	
105	impl Error for EncodeError {}
106	
107	/// Encodes decoded module data back into `.beam` container bytes.
108	///
109	/// The returned bytes decode to a [`ParsedModule`] equal to `module` (atoms,
110	/// instructions, imports, exports, lambdas, literals, strings, lines) when
111	/// loaded against the same `atom_table`.
112	pub fn encode_module(
113	    module: &ParsedModule,
114	    atom_table: &AtomTable,
115	) -> Result<Vec<u8>, EncodeError> {
116	    let encoder = AtomEncoder::new(&module.atoms, atom_table, module.type_chunk.is_some());
117	
118	    // Canonical chunk order.
119	    //
120	    // `AtU8`, `Code`, `ImpT`, `ExpT` and `StrT` are emitted UNCONDITIONALLY,
121	    // even when empty. Our own loader treats an absent optional chunk as empty
122	    // (`load.rs` reads `StrT` with `unwrap_or_default`), so omitting them round
123	    // trips perfectly through beamr and is invisible to our own suite — but
124	    // OTP's `beam_disasm` hard-requires all five and refuses the module with
125	    // `{missing_chunk, _, "StrT"}` (or `"ExpT"` / `"ImpT"`) when one is absent.
126	    // A module nobody else's tools can read is a module we cannot investigate
127	    // with the ecosystem's instruments, and that cost has already been paid
128	    // once: a 7,828-module sweep silently skipped our module because
129	    // `beam_disasm` would not open it.
130	    //
131	    // The required set was measured, not assumed — each chunk was stripped in
132	    // turn from a working module and fed to `beam_disasm` (OTP 29). `Attr`,
133	    // `CInf`, `Dbgi`, `Docs`, `Line`, `LocT`, `Meta` and `Type` are genuinely
134	    // optional and stay conditional. `FunT` is likewise not required. `LitT`
135	    // remains conditional: stripping it from a module that HAS literals leaves
136	    // dangling references, so that arm of the experiment is a confound rather
137	    // than evidence that it is mandatory.
138	    let mut chunks: Vec<(&[u8; 4], Vec<u8>)> = vec![
139	        (b"AtU8", encode_atom_chunk(&module.atoms, &encoder)?),
140	        (b"Code", encode_code_chunk(&module.instructions, &encoder)?),
141	        (b"ImpT", encode_import_chunk(&module.imports, &encoder)?),
142	        (b"ExpT", encode_export_chunk(&module.exports, &encoder)?),
143	    ];
144	    if !module.lambdas.is_empty() {
145	        chunks.push((b"FunT", encode_lambda_chunk(&module.lambdas, &encoder)?));
146	    }
147	    if let Some(literal_chunk) = encode_literal_chunk(&module.literals, &encoder)? {
148	        chunks.push((b"LitT", literal_chunk));
149	    }
150	    chunks.push((b"StrT", encode_string_chunk(&module.string_table)));
151	    if !module.line_info.is_empty() {
152	        chunks.push((b"Line", encode_line_chunk(&module.line_info)?));
153	    }
154	    // VERBATIM, never rebuilt: typed-register operands in the Code chunk index
155	    // into these bytes, and only the identical bytes keep those indices valid
156	    // (#95). The chunk is opaque to beamr's own loader on purpose.
157	    if let Some(type_chunk) = &module.type_chunk {
158	        chunks.push((b"Type", type_chunk.clone()));
159	    }
160	
161	    Ok(frame_container(&chunks))
162	}
163	
164	/// Frames chunk bodies into the outer `FOR1 … BEAM` container.
165	fn frame_container(chunks: &[(&[u8; 4], Vec<u8>)]) -> Vec<u8> {
166	    let mut body = Vec::new();
167	    body.extend_from_slice(b"BEAM");
168	    for (tag, chunk) in chunks {
169	        body.extend_from_slice(*tag);
170	        // A chunk body never approaches 4 GiB in practice; the loader itself
171	        // reads the length as `u32`, so a wider value could not round-trip.
172	        body.extend_from_slice(&(chunk.len() as u32).to_be_bytes());
173	        body.extend_from_slice(chunk);
174	        let padding = (4 - (chunk.len() % 4)) % 4;
175	        body.resize(body.len() + padding, 0);
176	    }
177	
178	    let mut out = Vec::with_capacity(8 + body.len());
179	    out.extend_from_slice(b"FOR1");
180	    out.extend_from_slice(&(body.len() as u32).to_be_bytes());
181	    out.extend_from_slice(&body);
182	    out
183	}

1	//! B-1 proof obligations for the stable compile seam: `awl_hello` end to
2	//! end (bytes, contracts, actions, determinism), call-site node overrides in
3	//! the requirement derivation, and lossless diagnostic passthrough for both
4	//! lowering refusals and language errors.
5	
6	use std::fmt::Write as _;
7	use std::fs;
8	use std::path::{Path, PathBuf};
9	
10	use aion_awl::mir::{LowerError, lower, select};
11	use aion_awl::{CompileError, Span, action_requirements, compile};
12	
13	type TestResult = Result<(), Box<dyn std::error::Error>>;
14	
15	fn manifest_dir() -> PathBuf {
16	    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
17	}
18	
19	fn hex(bytes: &[u8]) -> String {
20	    let mut out = String::with_capacity(bytes.len() * 2);
21	    for byte in bytes {
22	        let _ = write!(out, "{byte:02x}");
23	    }
24	    out
25	}
26	
27	fn fixture(relative: &str) -> PathBuf {
28	    manifest_dir().join("tests/fixtures/rev2").join(relative)
29	}
30	
31	fn unhex(text: &str) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
32	    let text = text.trim();
33	    Ok((0..text.len())
34	        .step_by(2)
35	        .map(|i| u8::from_str_radix(&text[i..i + 2], 16))
36	        .collect::<Result<Vec<u8>, _>>()?)
37	}
38	
39	type BeamChunk = (String, Vec<u8>);
40	
41	/// Splits a BEAM container into its `(name, payload)` chunk sequence.
42	fn beam_chunks(bytes: &[u8]) -> Result<Vec<BeamChunk>, Box<dyn std::error::Error>> {
43	    assert!(bytes.starts_with(b"FOR1"), "not a BEAM container");
44	    let mut chunks = Vec::new();
45	    let mut offset = 12;
46	    while offset + 8 <= bytes.len() {
47	        let name = String::from_utf8(bytes[offset..offset + 4].to_vec())?;
48	        let size_bytes: [u8; 4] = bytes[offset + 4..offset + 8].try_into()?;
49	        let size = u32::from_be_bytes(size_bytes);
50	        let payload = bytes[offset + 8..offset + 8 + size as usize].to_vec();
51	        chunks.push((name, payload));
52	        offset += 8 + (size as usize).div_ceil(4) * 4;
53	    }
54	    Ok(chunks)
55	}
56	
57	/// `LitT` table content behind either container form: a zero u32 size prefix
58	/// marks the raw uncompressed table (beamr 0.15.3's ENC-001 determinism form),
59	/// while a nonzero prefix declares the decompressed size of the zlib stream
60	/// that follows (the pre-0.15.3 form the committed goldens carry).
61	fn litt_content(payload: &[u8]) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
62	    let declared_bytes: [u8; 4] = payload[..4].try_into()?;
63	    let declared = u32::from_be_bytes(declared_bytes);
64	    if declared == 0 {
65	        return Ok(payload[4..].to_vec());
66	    }
67	    let mut out = Vec::new();
68	    std::io::Read::read_to_end(&mut flate2::read::ZlibDecoder::new(&payload[4..]), &mut out)?;
69	    if out.len() != declared as usize {
70	        return Err(format!(
71	            "LitT declared decompressed size {declared} but the stream inflated to {} bytes",
72	            out.len()
73	        )
74	        .into());
75	    }
76	    Ok(out)
77	}
78	
79	/// Byte-equality per chunk, except `LitT`: its container form varies with the
80	/// beamr version (compressed pre-0.15.3, zero-prefix uncompressed after
81	/// ENC-001) and its deflate stream varies with the cargo feature graph. The
82	/// literal table content is the contract.
83	fn beam_equivalent(actual: &[u8], expected: &[u8]) -> TestResult {
84	    let actual_chunks = beam_chunks(actual)?;
85	    let expected_chunks = beam_chunks(expected)?;
86	    let names = |chunks: &[BeamChunk]| {
87	        chunks
88	            .iter()
89	            .map(|(name, _)| name.clone())
90	            .collect::<Vec<_>>()
91	    };
92	    assert_eq!(
93	        names(&actual_chunks),
94	        names(&expected_chunks),
95	        "chunk sequence drifted from the committed golden"
96	    );
97	    for ((name, actual_payload), (_, expected_payload)) in
98	        actual_chunks.iter().zip(expected_chunks.iter())
99	    {
100	        if name == "LitT" {
101	            assert_eq!(
102	                litt_content(actual_payload)?,
103	                litt_content(expected_payload)?,
104	                "LitT literal content drifted from the committed golden"
105	            );
106	        } else {
107	            assert_eq!(
108	                actual_payload, expected_payload,
109	                "chunk {name} drifted from the committed golden"
110	            );
111	        }
112	    }
113	    Ok(())
114	}
115	
116	fn read(path: &Path) -> Result<(String, PathBuf), Box<dyn std::error::Error>> {
117	    let source = fs::read_to_string(path)?;
118	    let root = path
119	        .parent()
120	        .ok_or_else(|| format!("{} has no parent directory", path.display()))?
121	        .to_path_buf();
122	    Ok((source, root))
123	}
124	
125	/// Obligation 1: `awl_hello` compiles; the bytes match the committed
126	/// `awl_hello.beam.hex` golden chunk-canonically (`assert_beam_equivalent`:
127	/// every chunk byte-equal except `LitT`, which compares decompressed; set
128	/// `AWL_BC2_BLESS=1` to re-bless — never implicit) AND the direct MIR path's
129	/// `select` output; the sidecar matches the committed `.gleam_types.hex`
130	/// golden; two calls are identical.
131	#[test]
132	fn awl_hello_compiles_deterministically_to_the_select_bytes() -> TestResult {
133	    let (source, root) = read(&fixture("flagship/valid/awl_hello.awl"))?;
134	    let first = compile(&source, &root).map_err(|error| error.to_string())?;
135	    let second = compile(&source, &root).map_err(|error| error.to_string())?;
136	
137	    assert_eq!(first.workflow_name, "awl_hello");
138	    assert!(first.beam_bytes.starts_with(b"FOR1"));
139	    assert_eq!(first.beam_bytes, second.beam_bytes, "beam bytes drift");
140	    assert_eq!(first.sidecar_bytes, second.sidecar_bytes, "sidecar drift");
141	    assert_eq!(first, second, "compile is not a pure function of source");
142	
143	    let document = aion_awl::parse(&source)?;
144	    let module = lower(&document, Some(&root))?;
145	    assert_eq!(
146	        first.beam_bytes,
147	        select(&module)?,
148	        "compile bytes differ from the direct MIR path"
149	    );
150	    assert!(!first.sidecar_bytes.is_empty(), "sidecar bytes are empty");
151	
152	    let golden_root = manifest_dir().join("tests/mir-goldens/flagship/valid");
153	    let beam_golden = golden_root.join("awl_hello.beam.hex");
154	    let beam_hex = hex(&first.beam_bytes);
155	    if std::env::var("AWL_BC2_BLESS").is_ok() {
156	        fs::write(&beam_golden, &beam_hex)?;
157	    }
158	    let expected = fs::read_to_string(&beam_golden).map_err(|error| {
159	        format!(
160	            "missing beam golden {} (run with AWL_BC2_BLESS=1 to create): {error}",
161	            beam_golden.display()
162	        )
163	    })?;
164	    beam_equivalent(&first.beam_bytes, &unhex(&expected)?)?;
165	    assert_eq!(
166	        hex(&first.sidecar_bytes),
167	        fs::read_to_string(golden_root.join("awl_hello.gleam_types.hex"))?,
168	        "sidecar bytes differ from the committed golden"
169	    );
170	    Ok(())
171	}
