1	//! Freshness guard for the committed SDK closure: rebuild the oracle Gleam
2	//! project (`examples/awl-hello`, the exact tree `regen-awl-sdk-closure.sh`
3	//! harvests) and export-set-compare the fresh harvest against the committed
4	//! `sdk-closure/` beams — the same rebuild-and-compare pattern as the
5	//! ops-console embed freshness guard.
6	//!
7	//! A stale committed bundle (an SDK edit without a closure regeneration)
8	//! fails here in CI instead of failing at runtime in a deployed direct
9	//! archive. Requires a local `gleam` toolchain, exactly like the AWL emitter
10	//! compile-proof tests.
11	//!
12	//! Comparison runs on two axes, because neither alone catches what the guard
13	//! exists to catch:
14	//!
15	//! 1. **Export sets** — the wire surface generated code links against. This
16	//!    axis produces the better diagnostic: it names the functions gained and
17	//!    lost.
18	//! 2. **Behavioural chunk bytes** — what actually *runs*. An SDK edit that
19	//!    changes a function body (a bug fix, a corrected branch, a changed error
20	//!    message) changes neither the module set nor any export set, so axis 1 is
21	//!    blind to precisely the case the guard was written for. The closure ships
22	//!    as bytes and the bytes execute in a deployed direct archive.
23	//!
24	//! Axis 2 compares an ALLOWLIST of chunks rather than whole files. A beam
25	//! carries `CInf` (compile time, source path, options) and other metadata that
26	//! differs between two builds of identical source, so whole-file equality would
27	//! flap. An allowlist — rather than an exclude list — means an unrecognised or
28	//! newly-introduced volatile chunk cannot leak in and make the gate a coin
29	//! flip: anything not named here is ignored by construction.
30	//!
31	//! The remedy for a failure on either axis is the same single action — run
32	//! `scripts/regen-awl-sdk-closure.sh` and commit the result — so the messages
33	//! name which axis diverged only to tell an SDK edit from a toolchain move at a
34	//! glance.
35	
36	#[path = "test_support/gleam.rs"]
37	mod gleam_test_support;
38	
39	use std::collections::BTreeSet;
40	use std::fs;
41	use std::path::{Path, PathBuf};
42	
43	use aion_awl_package::{sdk_closure_modules, sdk_closure_version};
44	use beamr::atom::AtomTable;
45	use beamr::loader::load_beam_chunks;
46	
47	type TestResult = Result<(), Box<dyn std::error::Error>>;
48	
49	fn workspace_root() -> PathBuf {
50	    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
51	}
52	
53	/// SDK test-only modules the regeneration script excludes from the
54	/// `aion_flow` package (mirrors `excluded()` in
55	/// `scripts/regen-awl-sdk-closure.sh`).
56	fn excluded_sdk_module(package: &str, module: &str) -> bool {
57	    package == "aion_flow"
58	        && (module == "aion_flow_ffi"
59	            || module == "aion@testing"
60	            || module.starts_with("aion@testing@"))
61	}
62	
63	/// Exported `(function, arity)` set of one beam file.
64	fn export_set(bytes: &[u8]) -> Result<BTreeSet<(String, u32)>, Box<dyn std::error::Error>> {
65	    let atoms = AtomTable::with_common_atoms();
66	    let parsed = load_beam_chunks(bytes, &atoms)?;
67	    let mut set = BTreeSet::new();
68	    for export in &parsed.exports {
69	        let function = atoms
70	            .resolve(export.function)
71	            .ok_or_else(|| format!("unresolvable export atom: {:?}", export.function))?;
72	        set.insert((function.to_owned(), u32::from(export.arity)));
73	    }
74	    Ok(set)
75	}
76	
77	/// Beam chunks whose bytes decide what the module DOES.
78	///
79	/// `Code` is the instruction stream; `AtU8`/`Atom` the atom table those
80	/// instructions index; `LitT`/`StrT` the literal and string tables they load
81	/// from; `ImpT`/`ExpT`/`LocT` the import, export and local-function tables that
82	/// resolve calls; `FunT` the closure table. Every one is a deterministic
83	/// function of source plus compiler, so an unchanged source rebuilt by an
84	/// unchanged toolchain reproduces them exactly.
85	///
86	/// Everything else — `CInf` (compile timestamp, source path, options), `Dbgi`,
87	/// `Docs`, `Line` — is metadata or debug information and is ignored by
88	/// omission. An allowlist is deliberate: an exclude list would have to be
89	/// extended every time a toolchain introduces a new volatile chunk, and the
90	/// failure mode of forgetting is a gate that flaps.
91	const BEHAVIOURAL_CHUNKS: &[&[u8; 4]] = &[
92	    b"Atom", b"AtU8", b"Code", b"ExpT", b"FunT", b"ImpT", b"LitT", b"LocT", b"StrT",
93	];
94	
95	/// The behaviour-deciding chunks of one beam file, keyed by chunk id.
96	///
97	/// Walks the IFF container directly (`FOR1` + length + `BEAM`, then
98	/// id/length/payload records padded to a four-byte boundary) rather than going
99	/// through a beam loader: the guard must compare the bytes as shipped, and a
100	/// loader that normalised or re-encoded anything would compare its own output
101	/// instead of the artifact.
102	fn behavioural_chunks(
103	    bytes: &[u8],
104	) -> Result<std::collections::BTreeMap<String, Vec<u8>>, Box<dyn std::error::Error>> {
105	    if bytes.len() < 12 || &bytes[0..4] != b"FOR1" || &bytes[8..12] != b"BEAM" {
106	        return Err("not a BEAM IFF container".into());
107	    }
108	    let mut chunks = std::collections::BTreeMap::new();
109	    let mut offset = 12usize;
110	    while offset + 8 <= bytes.len() {
111	        let id: [u8; 4] = bytes[offset..offset + 4].try_into()?;
112	        let size = u32::from_be_bytes(bytes[offset + 4..offset + 8].try_into()?) as usize;
113	        let start = offset + 8;
114	        let end = start
115	            .checked_add(size)
