231	/// Recursive half of [`project_modules`]. `prefix` is the already-flattened
232	/// package path, empty at the source root.
233	fn collect_modules(
234	    directory: &Path,
235	    prefix: &str,
236	    into: &mut Vec<String>,
237	) -> Result<(), GleamBuildFailure> {
238	    for entry in fs::read_dir(directory).map_err(|error| io_failure(directory, &error))? {
239	        let entry = entry.map_err(|error| io_failure(directory, &error))?;
240	        let path = entry.path();
241	        let name = entry.file_name();
242	        let Some(name) = name.to_str() else {
243	            return Err(GleamBuildFailure::new(format!(
244	                "non-UTF-8 entry under {}: the compiled module name it maps to cannot be proven",
245	                directory.display()
246	            )));
247	        };
248	        if path.is_dir() {
249	            let nested = format!("{prefix}{name}@");
250	            collect_modules(&path, &nested, into)?;
251	        } else if let Some(stem) = name.strip_suffix(".gleam") {
252	            into.push(format!("{prefix}{stem}"));
