138	/// Chunk ids that differ between two beams, restricted to the behavioural set.
139	///
140	/// Returns the ids rather than a boolean so a failure names what moved: a
141	/// `Code`-only divergence reads as a source edit, while a whole-set divergence
142	/// reads as a toolchain move.
143	fn divergent_chunks(
144	    fresh: &[u8],
145	    committed: &[u8],
146	) -> Result<Vec<String>, Box<dyn std::error::Error>> {
147	    let fresh = behavioural_chunks(fresh)?;
148	    let committed = behavioural_chunks(committed)?;
149	    // A BTreeSet, not `dedup()`: chaining two sorted key sets interleaves
150	    // them, so duplicates are not adjacent and `dedup()` would report every
151	    // divergent chunk twice.
152	    let divergent: BTreeSet<String> = fresh
153	        .keys()
154	        .chain(committed.keys())
155	        .filter(|id| fresh.get(*id) != committed.get(*id))
156	        .cloned()
157	        .collect();
158	    Ok(divergent.into_iter().collect())
159	}
