161	/// Flip the last byte of one named chunk's payload, in place.
162	///
163	/// Length-preserving on purpose: every following chunk keeps its offset, so the
164	/// result is a well-formed container that differs from the original in exactly
165	/// one chunk. Returns `None` when the beam has no such chunk or its payload is
166	/// empty.
167	fn flip_last_byte_of_chunk(bytes: &[u8], target: [u8; 4]) -> Option<Vec<u8>> {
168	    let mut offset = 12usize;
169	    while offset + 8 <= bytes.len() {
170	        let id: [u8; 4] = bytes[offset..offset + 4].try_into().ok()?;
171	        let size = u32::from_be_bytes(bytes[offset + 4..offset + 8].try_into().ok()?) as usize;
172	        let start = offset + 8;
173	        let end = start.checked_add(size)?;
174	        if end > bytes.len() {
175	            return None;
176	        }
177	        if id == target && size > 0 {
178	            let mut mutated = bytes.to_vec();
179	            mutated[end - 1] ^= 0xFF;
180	            return Some(mutated);
181	        }
182	        offset = end + (4 - (size % 4)) % 4;
183	    }
184	    None
185	}
