195	/// **The pin.** A changed function body with the export surface held constant
196	/// is invisible to the export-set axis and caught by the byte axis.
197	///
198	/// This is the whole finding behind #115: the export-set comparison was chosen
199	/// precisely because beam bytes are volatile, and the exclusion swallowed the
200	/// inclusion — "an SDK edit without a closure regeneration" is the case the
201	/// guard exists for, and it changes no export set. Asserting the export sets
202	/// are EQUAL first is what makes the byte assertion non-vacuous: without it, a
203	/// mutation that happened to alter exports would satisfy the second assertion
204	/// while proving nothing about blindness.
205	///
206	/// Runs without a `gleam` toolchain: it mutates a committed beam rather than
207	/// harvesting a fresh one, so the mechanism is gated in every battery even
208	/// where the oracle project cannot be built.
209	#[test]
210	fn a_changed_body_is_invisible_to_exports_and_caught_by_bytes() -> TestResult {
211	    let (module, committed) = a_committed_beam()?;
212	    // Try the behavioural chunks a body edit actually moves. `Code` is the
213	    // instruction stream; `StrT`/`LitT` hold the string and literal tables a
214	    // changed error message lands in. Whichever the beam carries, the mutant
215	    // must still parse — a corrupted beam that fails to load would prove
216	    // nothing about export-set blindness.
217	    let mut proven = None;
218	    for chunk in [*b"Code", *b"StrT", *b"LitT"] {
219	        let Some(mutated) = flip_last_byte_of_chunk(committed, chunk) else {
220	            continue;
221	        };
222	        let Ok(mutated_exports) = export_set(&mutated) else {
223	            continue;
224	        };
225	        if mutated_exports != export_set(committed)? {
226	            continue;
227	        }
228	        proven = Some((String::from_utf8_lossy(&chunk).into_owned(), mutated));
229	        break;
230	    }
231	    let (chunk, mutated) = proven.ok_or_else(|| {
232	        format!(
233	            "no behavioural chunk of `{module}` could be perturbed while holding the export set \
234	             constant — the pin cannot demonstrate what it exists to demonstrate"
